-- Ejecutar dentro de la base PostgreSQL creada por Render.
CREATE TABLE "Mascota" (
    "MascotaId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(80) NOT NULL,
    "Especie" VARCHAR(40) NOT NULL,
    "Edad" INTEGER NOT NULL CHECK ("Edad" BETWEEN 0 AND 40),
    "CodigoChip" VARCHAR(25) NOT NULL UNIQUE
);

CREATE TABLE "Cita" (
    "CitaId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FechaHora" TIMESTAMP NOT NULL,
    "Motivo" VARCHAR(150) NOT NULL,
    "Veterinario" VARCHAR(80) NOT NULL,
    "MascotaId" INTEGER NOT NULL,
    CONSTRAINT "FK_Cita_Mascota" FOREIGN KEY ("MascotaId") REFERENCES "Mascota"("MascotaId"),
    CONSTRAINT "UQ_Cita_Mascota_Fecha" UNIQUE ("MascotaId", "FechaHora")
);

